import React from 'react';
import { ImageBackground, ImageBackgroundProps } from 'react-native';
import {
    SafeAreaContainer,
    SimpleHeaderProps,
    ActionButtonProps,
    SafeAreaContainerProps,
    useTheme,
    createStyles,
    GradientColorsType,
} from '@core/ui';
import { SharedValue } from 'react-native-reanimated';
import {
    useSafeAreaFrame,
    useSafeAreaInsets,
} from 'react-native-safe-area-context';
import { sources } from 'webpack';
import getImg from '@src/utils/getImg';

interface ScreenImageContainerProps {
    headerProps?: SimpleHeaderProps;
    safeAreaStyle?: SafeAreaContainerProps;
    gradientProps?: GradientColorsType;
    bottomActionProps?: ActionButtonProps;
    headerType?: string;
    scrollY?: SharedValue<number>;
    HeaderComponent?: React.FC<any>;
    imageBackgroundProps?: ImageBackgroundProps;
}

const BackgroundImageContainer: React.FC<
    React.PropsWithChildren<ScreenImageContainerProps>
> = ({
    safeAreaStyle = {},
    headerProps = {},
    imageBackgroundProps = {
        source: getImg('/assets/images/bg/bg_body.jpg')
    },
    children,
    bottomActionProps,
    scrollY,
    HeaderComponent,
}) => {
        const { theme } = useTheme();
        const styles = useStyles(theme);
        const { top } = useSafeAreaInsets();

        const { style: safeAreStyle, ...restSafeAreaProps } = safeAreaStyle;
        const { style: headerStyle, ...restHeaderProps } = headerProps;
        const {
            style: bottomStyle,
            title,
            ...restBottomProps
        } = bottomActionProps ?? {};

        return (
            <ImageBackground {...imageBackgroundProps} style={[styles.container]}>
                <SafeAreaContainer
                    style={[
                        styles.container,
                        safeAreaStyle,
                        {
                            marginTop: top,
                        },
                    ]}
                    bottomOffset={theme.Size.vs(16)}
                    keyboardOffset={title ? theme.Size.vs(16) : 0}
                    {...restSafeAreaProps}
                >
                    {children}
                </SafeAreaContainer>
            </ImageBackground>
        );
    };

const useStyles = createStyles((theme) => ({
    container: {
        flex: 1,
        backgroundColor: 'transparent',
    },
    bottom: {
        marginHorizontal: theme.Size.hs(16),
    },
}));

export { BackgroundImageContainer };
