import { useState, useCallback } from 'react';
import { contactPickerService, ContactResult } from '../services/contacts/ContactPickerService';

export const useContactPicker = () => {
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const openContactPicker = useCallback(async (onSelect: (result: ContactResult) => void) => {
        try {
            setIsLoading(true);
            setError(null);
            await contactPickerService.openContactPicker((result) => {
                onSelect(result);
                setIsLoading(false);
            });
        } catch (err) {
            setError(err instanceof Error ? err.message : 'Failed to pick contact');
            setIsLoading(false);
        }
    }, []);

    return {
        isLoading,
        error,
        openContactPicker,
    };
};
