import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { IDopSubmitV2Repository } from '@src/domain/interfaces/card_dop/dopSubmitV2';
import { DopSubmitV2DataReq } from '@src/domain/entities/card_dop/dopSubmitV2';

export class DopSubmitV2Handler {
    private readonly _repository: IDopSubmitV2Repository;

    constructor(
        @inject(TYPES.IDopSubmitV2Repository)
        dopSubmitV2: IDopSubmitV2Repository
    ) {
        this._repository = dopSubmitV2;
    }

    handle(query: Query<CardDOPBaseRequest<DopSubmitV2DataReq>>) {
        return this._repository.dopSubmitV2(query);
    }
}
