import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { IDopInitV2Repository } from '@src/domain/interfaces/card_dop/dopInitV2';
import { DopInitV2DataReq } from '@src/domain/entities/card_dop/dopInitV2';

export class DopInitV2Handler {
    private readonly _repository: IDopInitV2Repository;

    constructor(
        @inject(TYPES.IDopInitV2Repository)
        dopInitV2Repository: IDopInitV2Repository
    ) {
        this._repository = dopInitV2Repository;
    }

    handle(query: Query<CardDOPBaseRequest<DopInitV2DataReq>>) {
        return this._repository.dopInitV2(query);
    }
}
