import { Query } from '@src/domain/models/query';
import { createAsyncThunk } from '@reduxjs/toolkit';
import { TYPES } from '@src/di/types/types';
import { container } from '@src/di/inversify.config';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { GetCareersPositionsHandler } from '@src/application/card_dop/getCareersPositions_handler';
import { GetCareersPositionsDataReq } from '@src/domain/entities/card_dop/getCareersPositions';
import { DopInitV2Handler } from '@src/application/card_dop/dopInitV2_handler';
import { DopInitV2DataReq } from '@src/domain/entities/card_dop/dopInitV2';
import { DopSubmitV2DataReq } from '@src/domain/entities/card_dop/dopSubmitV2';
import { DopSubmitV2Handler } from '@src/application/card_dop/dopSubmitV2_handler';

export const fetchGetCareersPositions = createAsyncThunk('getCareersPositions/fetch', async (payload: CardDOPBaseRequest<GetCareersPositionsDataReq>['data']) => {
    const getCareersPositions = container.get<GetCareersPositionsHandler>(TYPES.GetCareersPositionsHandler);    
    const payloadReq = commonService.getPayload<CardDOPBaseRequest<GetCareersPositionsDataReq>, CardDOPBaseRequest<GetCareersPositionsDataReq>['data']>({ data: payload })    
    const query = new Query<CardDOPBaseRequest<GetCareersPositionsDataReq>>({
        query: {            
            ...payloadReq,
            screenName:"MFE-DOP-OCRScreen",            
        },
    });
    return await getCareersPositions.handle(query);
});

