import { eventBusService, Storage, STORAGE_KEY } from '@core/service';
import { SELFIE_VERIFICATION } from '@src/config';
import { HVFaceResponse } from '@src/domain/entities/hyperV/ekyc';
import { useState } from 'react';
import { FACE_STATUS, PortalManager } from '@core/ui';
import { ReduxState, useDispatch, useSelector } from '@src/lib/redux';
// import { getOnboardingId } from '@src/presentation/onboarding/components/PhoneRegister/selector';
// import { useNavigate } from './useNavigate';
import { NavigationProp, useNavigation } from '@react-navigation/native';
import { MainStackParamList } from '@src/presentation/navigation/MainNavigator';
import { useCustomNavigation } from './useCustomNavigation';
import { selectICData } from '@src/presentation/dop_ocr/redux/selector';
import { updateSelfieData } from '@src/presentation/dop_ocr/redux/slice';
import { useTranslation } from 'react-i18next';
import uuid from 'react-native-uuid'
import { fetchDopID } from '@src/presentation/dop_ocr/thunk';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { DopIDDataReq } from '@src/domain/entities/card_dop/dopID';
import { selectLeadId } from '@src/presentation/dop_cvp/redux/CVPSelector';
import { OCR_FACE } from '@src/utils/constants';

const useScanFaceService = () => {
    const { navigate, goBackFromNativeModules } = useCustomNavigation();
    const [isReady, setReady] = useState<boolean>(false);
    const ICData = useSelector(selectICData);
    const { t } = useTranslation(['ekyc']);
    const leadId = useSelector(selectLeadId)
    const token = Storage.retrieve(STORAGE_KEY.USER_AUTH) || '';
    // const onboardingId = useSelector(getOnboardingId);
    const onboardingId = 'onboardingIdfortest';
    const dispatch = useDispatch();
    const openScanFace = () => {
        scanFace(onboardingId! || 'onboardingIdfortest', ICData?.frontImage!).catch();
    };
    const onVerifyFace = (transactionId: string, challengeId: string) => {
        verifyFace(transactionId, challengeId)
    }
    const scanFace = async (onboardingId: string, frontImage: string) => {
        const inputs = { idFrontImage: frontImage };
        eventBusService.emit('open_app', {
            appName: 'HypervergeApp',
            screen: 'FaceIdentityVerificationScreen',
            data: {
                transactionId: onboardingId,
                workflowId: SELFIE_VERIFICATION,
                callback: (resultData: object) => {
                    console.log('\x1b[31m phapv7_resultData_scan_face', resultData);
                    return onScanFaceCallback(resultData as any);
                },
                inputs,
            },
        });
    };
    const verifyFace = async (transactionId: string, challengeId: string) => {
        eventBusService.emit('verify_face_id',
            {
                accessToken: token?.accessToken || '',
                uuid: uuid.v4(),
                transactionId: transactionId,
                transactionPartnerId: 'Hyperverge',
                extraInfoOnPremise: 'face',
                challengeId: challengeId,
                callback: (isVerifySuccess: boolean) => {
                    console.log('\x1b[31m phapv7_resultData_verify_face', isVerifySuccess);
                    return onVerifyFaceCallback(isVerifySuccess);
                },
            });
    };
    const navigation = useNavigation<NavigationProp<MainStackParamList>>();
    const onHandlePositiveResult = async (result: HVFaceResponse) => {
        try {
            const selfieData = result.details;
            dispatch(updateSelfieData(selfieData));
            dispatch(fetchDopID({ payload: { leadId } as CardDOPBaseRequest<DopIDDataReq>['data'], apiType: OCR_FACE }));
            navigate('NFC')
        } catch {
            onHandleNegativeResult();
        }
    };
    const onHandleNegativeResult = () => {
        navigate('notify_screen', {
            data: {
                id: 'common-information',
                title: t('onScan.unclear_title'),
                content: t('onScan.scan_unclear.face_unclear'),
                primaryButton: {
                    isShow: true,
                    lable: t('onScan.scan_unclear.retry_text'),
                    onPress: () => {
                        PortalManager.dismissAll();
                        openScanFace();
                    }
                }
            },
        });
    };
    const onScanFaceCallback = async (res: object) => {
        const result = res as HVFaceResponse;
        switch (result.status) {
            case FACE_STATUS.USER_CANCELLED:
                goBackFromNativeModules();
                break;
            case FACE_STATUS.AUTO_APPROVED:
            case FACE_STATUS.NEEDS_REVIEW:
                await onHandlePositiveResult(result);
                break;
            case FACE_STATUS.AUTO_DECLINED:
                onHandleNegativeResult();
                break;
            case FACE_STATUS.ERROR:
            default:
                onHandleNegativeResult();
                break;
        }
    };
    const onVerifyFaceCallback = (isVerifySuccess: boolean) => {

    }
    return {
        isReady,
        openScanFace,
        onVerifyFace
    };
};

export { useScanFaceService };
