import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { AuthUserDataReq } from '@src/domain/entities/card_dop/authUser';
import type { IAuthUserRepository } from '@src/domain/interfaces/card_dop/authUser';

export class AuthUserHandler {
    private readonly _repository: IAuthUserRepository;

    constructor(
        @inject(TYPES.IAuthUserRepository)
        authUserRepository: IAuthUserRepository
    ) {
        this._repository = authUserRepository;
    }

    handle(query: Query<CardDOPBaseRequest<AuthUserDataReq>>) {
        return this._repository.authUser(query);
    }
}
