import { Query } from '@src/domain/models/query';
import { createAsyncThunk } from '@reduxjs/toolkit';
import { TYPES } from '@src/di/types/types';
import { container } from '@src/di/inversify.config';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { RegisterUserHandler } from '@src/application/card_dop/registerUser_handler';
import { RegisterUserDataReq } from '@src/domain/entities/card_dop/registerUser';

export const fetchRegisterUser = createAsyncThunk('registerUser/fetch', async (payload: CardDOPBaseRequest<RegisterUserDataReq>['data']) => {
    const registerUser = container.get<RegisterUserHandler>(TYPES.RegisterUserHandler);    
    const payloadReq = commonService.getPayload<CardDOPBaseRequest<RegisterUserDataReq>, CardDOPBaseRequest<RegisterUserDataReq>['data']>({ data: payload })    
    const query = new Query<CardDOPBaseRequest<RegisterUserDataReq>>({
        query: {            
            ...payloadReq,
            screenName:"MFE-DOP-RegisterUserScreen",            
        },
    });
    return await registerUser.handle(query);
});
