import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { IGetCareersPositionsRepository } from '@src/domain/interfaces/card_dop/getCareersPositions';
import { GetCareersPositionsDataReq } from '@src/domain/entities/card_dop/getCareersPositions';

export class GetCareersPositionsHandler {
    private readonly _repository: IGetCareersPositionsRepository;

    constructor(
        @inject(TYPES.IGetCareersPositionsRepository)
        getCareersPositionsRepository: IGetCareersPositionsRepository
    ) {
        this._repository = getCareersPositionsRepository;
    }

    handle(query: Query<CardDOPBaseRequest<GetCareersPositionsDataReq>>) {
        return this._repository.getCareersPositions(query);
    }
}
