import { injectable } from 'inversify';
import { CmsService } from '@core/service';
import { IDopCVPRepository } from '@src/domain/interfaces/cms/dop/dopCVP';
import { DopCVPDataRes } from '@src/domain/entities/cms/dop/dopCVP';
import { IGetNfcImageRepository } from '@src/domain/interfaces/cms/dop/getNfcImage';
import { GetNfcImageDataRes } from '@src/domain/entities/cms/dop/getNfcImage';

@injectable()
export class GetNfcImageRepository extends CmsService implements IGetNfcImageRepository {
    constructor() {
        super();
    }

    async getNfcImage(name: string): Promise<GetNfcImageDataRes> {
        try {
            const response = await this.get<GetNfcImageDataRes>('/upload/files', {
                params: {                    
                    'filters[name][$contains]': name
                },
            });
            console.log('thieuvq3__________NFC: ', JSON.stringify(response));
            return (response.data as GetNfcImageDataRes) ?? null;
        } catch (error) {
            throw error;
        }
    }
}
