import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { IRequestTelcoOtpRepository } from '@src/domain/interfaces/card_dop/requestTelcoOtp';
import { RequestOtpDataReq, RequestOtpDataRes } from '@src/domain/entities/card_dop/requestTelcoOtp';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class RequestTelcoOtpRepository
    extends HttpService
    implements IRequestTelcoOtpRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async requestTelcoOtp<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<RequestOtpDataRes>> {
        const request = query.query as unknown as RequestOtpDataReq;
        const url = '/dop-request-telco-otp';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })
        return response.data as CardDOPBaseResponse<RequestOtpDataRes>;
    }
}
