import { Query } from '@src/domain/models/query';
import { createAsyncThunk } from '@reduxjs/toolkit';
import { TYPES } from '@src/di/types/types';
import { container } from '@src/di/inversify.config';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { RequestTelcoOtpHandler } from '@src/application/card_dop/requestTelcoOtp_handler';
import { VerifyTelcoOtpDataReq } from '@src/domain/entities/card_dop/verifyTelcoOtp';
import { VerifyTelcoOtpHandler } from '@src/application/card_dop/verifyTelcoOtp_handler';
import { RequestOtpDataReq } from '@src/domain/entities/card_dop/requestTelcoOtp';
import { commonService } from '@src/infrastructure/network/networkService';
import { CardDetailsHandler } from '@src/application/card_dop/cardDetails_handler';
import { CardDetailsDataReq } from '@src/domain/entities/card_dop/cardDetails';
import { DopCVPHandler } from '@src/application/cms/dop/dopCVP_handler';

export const fetchRequestTelcoOtp = createAsyncThunk('requestTelcoOtp/fetch', async (payload: CardDOPBaseRequest<RequestOtpDataReq>['data']) => {
    const requestTelcoOtp = container.get<RequestTelcoOtpHandler>(TYPES.RequestTelcoOtpHandler);    
    const payloadReq = commonService.getPayload<CardDOPBaseRequest<RequestOtpDataReq>, CardDOPBaseRequest<RequestOtpDataReq>['data']>({ data: payload })    
    const query = new Query<CardDOPBaseRequest<RequestOtpDataReq>>({
        query: {            
            ...payloadReq,
            screenName:"MFE-DOP-ConfirmPhoneScreen",            
        },
    });
    return await requestTelcoOtp.handle(query);
});

