export const fetchDopCVP = createAsyncThunk(
    'dopCVP/fetch',
    async (segment: string) => {
        const dopCVP = container.get<DopCVPHandler>(TYPES.DopCVPHandler);
        return await dopCVP.handle(segment);
    },
);
