import React, { useEffect, useReducer, useRef, useState } from 'react';
import { SafeAreaView, ScrollView, ImageBackground, TouchableOpacity, View, Image, TextInput, Alert, KeyboardAvoidingView } from 'react-native';
import {
    LoadingBlockerView,
    SimpleHeader,
    ActionButton,
    GradientButton,
    MaterialTextInput,
    Spacer,
    Text,
    useTheme,
    BottomSheet,
    BottomSheetRef,
    PinInput,
    PortalManager,
} from '@core/ui';
import useCSS from '@src/presentation/style';

import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { useDispatch, useSelector } from '@src/lib/redux';
import { useTranslation } from 'react-i18next';

import getImg from '@src/utils/getImg';
import {
    selectStatus,
    selectError,
    selectAddrDetail,
    selectAddressTypeList,
    selectDistrictId,
    selectProvinceId,
    selectWardId,
    selectAddressType,
    selectProvinceName,
    selectDistrictName,
    selectWardName,
} from '@src/presentation/dop_card/redux/cardSelector';
import cardSlice from '@src/presentation/dop_card/redux/cardSlice';
import BottomSheetAddress from '../components/bottomSheetAddress/bottomSheetAddress';
import { Province } from '@src/domain/entities/address/province';
import { District } from '@src/domain/entities/address/district';
import { Ward } from '@src/domain/entities/address/ward';
import { IS_IOS } from '@core/service';
import { selectLeadId, selectPhone } from '../dop_cvp/redux/CVPSelector';
import { fetchAddCardInfo, fetchConfirmCardInfo, fetchDopInitV2, fetchDopSubmitV2 } from './thunk';
import { CardDOPBaseRequest, CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { AddCardInfoDataReq, AddCardInfoDataRes } from '@src/domain/entities/card_dop/addCardInfo';
import type { IAddressType } from './type';
import { DopInitV2DataReq, DopInitV2DataRes } from '@src/domain/entities/card_dop/dopInitV2';
import { DopSubmitV2DataReq, DopSubmitV2DataRes } from '@src/domain/entities/card_dop/dopSubmitV2';
import { selectCardActive } from '../dop_home/DOPHomeSelector';
import { ConfirmCardInfoDataReq, ConfirmCardInfoDataRes } from '@src/domain/entities/card_dop/confirmCardInfo';
import BottomSheetTnC2 from '../components/bottomSheetTnC/BottomSheetTnC2';
import CustomHeader from '../components/header/CustomHeader';
import { selectValidateOCRData } from '../redux/selector';

const DOPCardStep2Screen = () => {
    const css = useCSS();
    const dispatch = useDispatch();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { t } = useTranslation(['card']);
    const { theme } = useTheme();

    const status = useSelector(selectStatus);
    const error = useSelector(selectError);
    const refBSTnC = useRef<BottomSheetRef>(null);
    const refBSOTP = useRef<BottomSheetRef>(null);
    const leadId = useSelector(selectLeadId);
    const validateOCRData = useSelector(selectValidateOCRData);

    const [disabled, setDisabled] = useState(false);
    const addressTypeList = useSelector(selectAddressTypeList);
    const addressType = useSelector(selectAddressType);
    const addrDetail = useSelector(selectAddrDetail);
    const provinceId = useSelector(selectProvinceId);
    const provinceName = useSelector(selectProvinceName);
    const districtId = useSelector(selectDistrictId);
    const districtName = useSelector(selectDistrictName);
    const wardId = useSelector(selectWardId);
    const wardName = useSelector(selectWardName);
    const addressCombine = `${wardName || '___'}, ${districtName || '___'}, ${provinceName || '___'}`;

    const [showAddressCombine, setShowAddressCombine] = useState(false);

    const phoneNumber = useSelector(selectPhone);

    const cardActive = useSelector(selectCardActive);

    const [errorList, setErrorList] = useReducer((prev: Record<string, string>, next: Record<string, string>) => ({ ...prev, ...next }), {});
    const handleChangeAddressType = (item: IAddressType) => {
        dispatch(cardSlice.actions.setAddressType(item));
        if (!item?.type) {
            setErrorList({ addressType: 'Bắt buộc nhập' });
        } else {
            delete errorList?.addressType;
        }
    };
    const handleChangeAddressDetail = (text: string) => {
        dispatch(cardSlice.actions.setAddrDetail(text));
        if (!text) {
            setErrorList({ addrDetail: 'Bắt buộc nhập' });
        } else {
            delete errorList?.addrDetail;
        }
    };

    const handleConfirm = (cardType: 'P' | 'V') => {
        const valid = handleValidate();
        if (!valid) return;

        if (addressType && addrDetail && provinceId && districtId && wardId) {
            dispatch(
                fetchAddCardInfo({
                    leadId: leadId,
                    cardType: cardType, //P: Physical - V: Virtual
                    cardReceivingAddrDetail: addrDetail,
                    cardReceivingAddrProvinceId: provinceId,
                    cardReceivingAddrWardId: wardId,
                    cardReceivingAddrDistrictId: districtId,
                    cardReceivingAddrType: addressType.type, //	 Nơi nhận thẻ vật lí 01: Địa chỉ liên hệ; 02: Nơi làm việc; 03: Nơi thường trú
                } as CardDOPBaseRequest<AddCardInfoDataReq>['data']),
            ).then((res) => {
                const payload = res?.payload as CardDOPBaseResponse<AddCardInfoDataRes>;
                if (payload?.resultCode === '00' && payload?.data) {
                    dispatch(
                        fetchConfirmCardInfo({
                            leadId: leadId,
                        } as CardDOPBaseRequest<ConfirmCardInfoDataReq>['data']),
                    ).then((res) => {
                        const payload = res.payload as CardDOPBaseResponse<ConfirmCardInfoDataRes>;
                        if (payload?.resultCode === '00' && payload?.data) {
                            const { contract, tncTKTT, tncCard, tncFPT, prohibitedActs, document } = payload?.data;
                            const flow = 'NTB';
                            const dataNTB = [
                                {
                                    id: '1',
                                    content: t('tnc_ntb.p_1'),
                                    title1: 'Thỏa thuận mở, sử dụng TKTT/SP-DV',
                                    link1: `data:application/pdf;base64,${contract}`,
                                    title2: 'Văn bản Uỷ Quyền',
                                    link2: `data:application/pdf;base64,${document}`,
                                },
                                {
                                    id: '2',
                                    content: t('tnc_ntb.p_2'),
                                },
                                {
                                    id: '3',
                                    content: t('tnc_ntb.p_3'),
                                    title1: 'Điều khoản và điều kiện mở',
                                    link1: tncTKTT,
                                    title2: 'Điều khoản và điều kiện khi phát hành',
                                    link2: tncCard,
                                },
                                {
                                    id: '5',
                                    content: t('tnc_ntb.p_4'),
                                    title1: 'Dấu hiệu Hoa Kỳ',
                                    link1: tncFPT,
                                    title2: 'Không liên quan đến cá nhân có ảnh hưởng chính trị.',
                                    link2: prohibitedActs,
                                },
                                {
                                    id: '6',
                                    content: t('tnc_ntb.p_5'),
                                },
                            ];
                            const dataETB = [
                                {
                                    id: '1',
                                    content: t('tnc_ntb.p_1'),
                                    title1: 'Thỏa thuận mở, sử dụng TKTT/SP-DV',
                                    link1: `data:application/pdf;base64,${contract}`,
                                    title2: 'Văn bản Uỷ Quyền',
                                    link2: `data:application/pdf;base64,${document}`,
                                },
                                {
                                    id: '3',
                                    content: t('tnc_ntb.p_3'),
                                    title1: 'Điều khoản và điều kiện mở',
                                    link1: tncTKTT,
                                    title2: 'Điều khoản và điều kiện khi phát hành',
                                    link2: tncCard,
                                },
                                {
                                    id: '5',
                                    content: t('tnc_ntb.p_4'),
                                    title1: 'Dấu hiệu Hoa Kỳ',
                                    link1: tncFPT,
                                    title2: 'Không liên quan đến cá nhân có ảnh hưởng chính trị.',
                                    link2: prohibitedActs,
                                },
                                {
                                    id: '6',
                                    content: t('tnc_ntb.p_5'),
                                },
                            ];
                            PortalManager.present(() => (
                                <BottomSheet
                                    snapPoints={['75%']}
                                    safeAreaBottomOffset={IS_IOS ? 370 : 0}
                                    ref={refBSTnC}
                                    id={`bottomsheet-tnc`}
                                    title={t('tnc_ntb.title')}>
                                    <BottomSheetTnC2 onSubmit={handleSubmit} data={flow === 'NTB' ? dataNTB : dataETB} />
                                </BottomSheet>
                            ));
                        }
                    });
                }
            });
        } else {
            Alert.alert('Thông tin', 'Bạn chưa điền đủ thông tin');
        }
    };

    const DopInitV2 = async () => {
        return await dispatch(
            fetchDopInitV2({
                leadId: leadId || '',
            } as CardDOPBaseRequest<DopInitV2DataReq>['data']),
        );
    };

    const handleSubmit = () => {
        DopInitV2().then((res) => {
            if ((res.payload as CardDOPBaseResponse<DopInitV2DataRes>)?.resultCode === '00') {
                PortalManager.present(() => (
                    <BottomSheet
                        ref={refBSOTP}
                        id={`bottomsheet-otp`}
                        safeAreaBottomOffset={IS_IOS ? 370 : 0}
                        snapPoints={['70%']}
                        title={`Xác nhận OTP`}
                        description={`Vui lòng nhập mã OTP đã được gửi đến số điện thoại *${phoneNumber.slice(-3)}`}>
                        <View style={[css.items_center]}>
                            <PinInput cellCount={6} onChange={handleValueChangeOTP} />
                        </View>
                        <Spacer height={32} />
                        <ActionButton title={t('bs_otp_resend')} type='error' onPress={() => DopInitV2()} />
                    </BottomSheet>
                ));
            }
        });
    };

    const handleValueChangeOTP = (text: string) => {
        if (text.length === 6) {
            PortalManager.present(() => <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} />);
            dispatch(
                fetchDopSubmitV2({
                    leadId: leadId || '',
                    mediaType: '58',
                    challengeCode: '',
                    otp: text,
                } as CardDOPBaseRequest<DopSubmitV2DataReq>['data']),
            )
                .then((res) => {
                    if ((res.payload as CardDOPBaseResponse<DopSubmitV2DataRes>)?.resultCode === '00') {
                        navigation.navigate('dop_result_screen');
                    } else {
                        Alert.alert('Thông báo', (res.payload as CardDOPBaseResponse<DopSubmitV2DataRes>).resultMessage || 'Có lỗi xảy ra');
                    }
                    refBSOTP?.current?.close();
                    PortalManager.dismissAll();
                })
                .catch(() => {
                    PortalManager.dismissAll();
                });
        }
    };

    const handleValidate = () => {
        let valid = true;
        if (!addressType?.type) {
            setErrorList({ addressType: 'Bắt buộc nhập' });
            valid = false;
        } else {
            delete errorList?.addressType;
            valid = true;
        }
        if (!addrDetail) {
            setErrorList({ addrDetail: 'Bắt buộc chọn' });
            valid = false;
        } else {
            delete errorList?.addrDetail;
            valid = true;
        }

        if (!wardId) {
            setErrorList({ wardId: 'Bắt buộc nhập' });
            valid = false;
        } else {
            delete errorList?.wardId;
            valid = true;
        }
        return valid;
    };

    useEffect(() => {
        if (error) {
            Alert.alert('Thông báo', error);
        }
    }, [error]);

    useEffect(() => {
        if (validateOCRData?.addrDetail) {
            dispatch(cardSlice.actions.setAddrDetail(validateOCRData?.addrDetail));
        }
        if (validateOCRData?.addrWardName && validateOCRData?.addrWardId) {
            dispatch(cardSlice.actions.setWard({ wardId: validateOCRData?.addrWardId, wardName: validateOCRData?.addrWardName }));
        }
        if (validateOCRData?.addrDistrictName && validateOCRData?.addrDistrictId) {
            dispatch(cardSlice.actions.setDistrict({ districtId: validateOCRData?.addrDistrictId, districtName: validateOCRData?.addrDistrictName }));
        }
        if (validateOCRData?.addrProvinceName && validateOCRData?.addrProvinceId) {
            dispatch(cardSlice.actions.setProvince({ provinceId: validateOCRData?.addrProvinceId, provinceName: validateOCRData?.addrProvinceName }));
        }
    }, [])
    return (
        <>
            <KeyboardAvoidingView behavior={IS_IOS ? 'padding' : 'height'} style={[css.flex_1]}>
                <ImageBackground source={getImg('/assets/images/bg_body.jpg')} resizeMode='cover' style={{ flex: 1 }}>
                    <SafeAreaView style={[css.flex_1]}>
                        <CustomHeader
                            title={`Phát hành thẻ tín dụng`}
                            customGoBack={() => {
                                navigation.goBack();
                                dispatch(cardSlice.actions.setError(''));
                            }}
                        />

                        <ScrollView contentContainerStyle={[css.flex_1, css.ph_medium]}>
                            <Spacer height={16} />
                            <Image source={{ uri: cardActive?.image }} style={{ width: theme.Scaling.hs(76), height: theme.Scaling.vs(112) }} />
                            <Spacer height={24} />
                            <Text style={[css.page_title]}>Sắp xong rồi</Text>
                            <Text style={[css.page_sub_title, css.mt_base]}>chỉ cần xác nhận địa chỉ nhận thẻ nữa thôi!</Text>
                            <Spacer height={24} />
                            <View>
                                <Text style={[css.text_caption_100, css.font_regular, css.text_neutral_500, css.mb_base]}>Loại địa chỉ</Text>
                                <ScrollView horizontal>
                                    <View style={[css.row]}>
                                        {addressTypeList?.map((item: IAddressType, index) => (
                                            <TouchableOpacity
                                                key={`key-${item.type}`}
                                                onPress={() => handleChangeAddressType(item)}
                                                style={[
                                                    css.border_1,
                                                    css.rounded_full,
                                                    css.ph_medium,
                                                    css.pv_base,
                                                    item?.type === addressType?.type ? css.border_red_600 : css.border_neutral_300,
                                                    index > 0 ? css.ml_base : null,
                                                ]}>
                                                <Text style={[css.font_semibold, item === addressType ? css.text_red_600 : null]}>{item?.name}</Text>
                                            </TouchableOpacity>
                                        ))}
                                    </View>
                                </ScrollView>
                                {errorList?.addressType ? (
                                    <Text style={[css.text_red_600, css.text_subheadline, css.font_regular, css.mt_small]}>{errorList?.addressType}</Text>
                                ) : null}
                            </View>
                            <Spacer height={16} />
                            <View>
                                <MaterialTextInput label='Số nhà, tên đường' value={addrDetail} onChangeText={(text) => handleChangeAddressDetail(text)} />
                                {errorList?.addrDetail ? (
                                    <Text style={[css.text_red_600, css.text_subheadline, css.font_regular, css.mt_small]}>{errorList?.addrDetail}</Text>
                                ) : null}
                            </View>
                            <Spacer height={16} />

                            <View>
                                <TouchableOpacity
                                    style={[css.row, css.border_b_1, css.border_b_neutral_300, css.pv_base]}
                                    onPress={() => setShowAddressCombine(true)}>
                                    <View style={[css.flex_1]}>
                                        <Text style={[css.text_neutral_500, css.text_caption_100, css.font_regular, css.mb_small]}>
                                            Phường, Quận, Thành phố
                                        </Text>
                                        <View>
                                            <TextInput
                                                readOnly
                                                value={addressCombine}
                                                placeholder='...'
                                                onPress={() => setShowAddressCombine(true)}
                                                style={[css.text_body, css.font_regular, css.w_full]}
                                            />
                                        </View>
                                    </View>
                                    <Image
                                        style={[
                                            css.shrink_0,
                                            css.ml_base,
                                            { height: theme.Size.Vertical.xLarge, width: theme.Size.Horizontal.xLarge, resizeMode: 'contain' },
                                        ]}
                                        source={getImg('/assets/images/icons/icon_arrow_down.png')}
                                    />
                                </TouchableOpacity>
                                {errorList?.wardId ? (
                                    <Text style={[css.text_red_600, css.text_subheadline, css.font_regular, css.mt_small]}>{errorList?.wardId}</Text>
                                ) : null}
                            </View>

                            <View style={[css.mt_auto]}>
                                <ActionButton title={'Tôi chỉ cần sử dụng thẻ ảo'} type={'secondary'} onPress={() => handleConfirm('V')} />
                                <Spacer height={8} />
                                {disabled ? (
                                    <ActionButton title={'Xác nhận'} state='disabled' />
                                ) : (
                                    <GradientButton title={'Xác nhận'} gradientProps={{ type: 'primary' }} onPress={() => handleConfirm('P')} />
                                )}
                            </View>
                        </ScrollView>
                    </SafeAreaView>
                </ImageBackground>
            </KeyboardAvoidingView>
            <BottomSheetAddress
                show={showAddressCombine}
                onClose={() => {
                    setShowAddressCombine(false);
                }}
                selectProvince={(item: Province) => {
                    dispatch(
                        cardSlice.actions.setProvince({
                            provinceId: item.id,
                            provinceName: item.name,
                        }),
                    );
                }}
                selectDistrict={(item: District) => {
                    dispatch(
                        cardSlice.actions.setDistrict({
                            districtId: item.id,
                            districtName: item.name,
                        }),
                    );
                }}
                selectWard={(item: Ward) => {
                    dispatch(
                        cardSlice.actions.setWard({
                            wardId: item.id,
                            wardName: item.name,
                        }),
                    );
                    setShowAddressCombine(false);
                    if (!item?.id) {
                        setErrorList({ wardId: 'Bắt buộc nhập' });
                    } else {
                        delete errorList?.wardId;
                    }
                }}
            />
            {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
        </>
    );
};

export default DOPCardStep2Screen;
